postmortem.raw:
{
  "root_cause": "Ambiguous instruction to 'clear out the stale test records' without clear definition of what constitutes 'stale' or 'test records', and no verification step before execution",
  "contributing": [
    "A4 (Runner) executed the command exactly as given without questioning or seeking clarification",
    "No verification mechanism was built into the process to confirm which records would be affected",
    "Lack of clear tagging or identification system for test vs. live records",
    "No approval gate or confirmation step before executing destructive operations"
  ],
  "who_is_accountable": "A4 (Runner) - as the executor of the command, but also the instruction-giver who provided insufficient clarity",
  "actions": [
    {
      "change": "Implement a two-step verification process for all destructive operations",
      "so_that": "Prevent accidental deletion of live data even when instructions are ambiguous"
    },
    {
      "change": "Require explicit confirmation from human reviewer before executing any delete operation",
      "so_that": "Ensure intentional action rather than blind execution of commands"
    },
    {
      "change": "Establish clear tagging standards for test vs. live records",
      "so_that": "Make it impossible to accidentally target real customer data during cleanup operations"
    }
  ],
  "what_i_tell_a4": "A4, you must never execute any command that could delete or modify data without explicit confirmation from a human reviewer. Your role is to execute exactly what you're told, but you must always ask for clarification when commands are ambiguous or potentially destructive. Never assume intent - always verify with a human before proceeding with any operation that affects real data."
}

